/**
 * Extracts the conditional plugin directory chain from a file path — every `if` or
 * `hosted_plugins` marker plus the plugin segment that follows it, joined in path order
 * (e.g. `if/com.plugin` from `.../if/com.plugin/update/x.xml`, or
 * `hosted_plugins/com.plugin1/if/com.plugin2` from a hosted plugin's own `if` directory at
 * `.../hosted_plugins/com.plugin1/if/com.plugin2/...`).
 *
 * Two conditional records belong to the same app only when this value matches, so it is used
 * both for grouping descendants and for detecting conditional conflicts. Returns undefined
 * when the path is not under a conditional directory.
 *
 * Matches either path separator so it behaves the same on POSIX and Windows.
 */
export declare function getConditionalPluginDir(filePath: string): string | undefined;
